<script setup>
import DashboardAdmin from '~/components/dashboard/Admin.vue'
import { money, today, initials } from '#shared/utils/format.js'
const { user, isOffice, isLocationAdmin } = useAuth()
const date = ref(today())
const { data, refresh, error, status } = await useFetch('/api/dashboard', { query: { date } })
usePolling(refresh)
const metrics = computed(() => data.value?.metrics || {})
const maxRevenue = computed(() => Math.max(...(data.value?.chart || []).map(d => d.revenue), 1))
const cards = computed(() => [
 {label:'Orders hari ini',value:metrics.value.ordersToday || 0,icon:'orders',note:`${metrics.value.newOrders || 0} order baru`,tone:'green'},
 {label:'Menunggu assignment',value:metrics.value.waitingAssignment || 0,icon:'dispatch',note:'Siap untuk di-dispatch',tone:'amber'},
 {label:'Treatment aktif',value:metrics.value.activeJobs || 0,icon:'therapists',note:`${metrics.value.inProgress || 0} treatment berjalan`,tone:'blue'},
 {label:'Pendapatan hari ini',value:money(metrics.value.revenue),icon:'payments',note:`${metrics.value.completed || 0} treatment selesai`,tone:'green'}
])
</script><template><DashboardAdmin v-if="isLocationAdmin" :data="data" :date="date" :error="error" :status="status" @update-date="date=$event" @refresh="refresh" /><div v-else><LayoutPageHeader :title="'Selamat datang, '+(user?.name.split(' ')[0] || '')" description="Ringkasan operasional spa Anda. Semua terkendali, dalam satu tempat." eyebrow="YOUR DAILY OVERVIEW"><input v-model="date" type="date" aria-label="Tanggal dashboard" class="date-control" /><UiButton v-if="isOffice" to="/orders/new"><UiIcon name="plus" :size="17" />Buat order</UiButton></LayoutPageHeader><div v-if="error" class="error-message">Dashboard gagal dimuat. <button class="text-link" @click="refresh">Coba lagi</button></div><div class="welcome-banner"><div class="banner-icon"><UiIcon name="leaf" :size="30" /></div><div><h3>A little clarity for a beautiful day.</h3><p>{{ metrics.availableTherapists || 0 }} therapist siap melayani. Pastikan setiap customer mendapatkan perhatian terbaik.</p></div><NuxtLink to="/dispatch">Buka dispatch <UiIcon name="arrow" :size="17" /></NuxtLink><div class="banner-leaf"><UiIcon name="leaf" :size="130" /></div></div><div class="metrics-grid"><div v-for="card in cards" :key="card.label" class="metric-card"><div class="metric-top"><span>{{ card.label }}</span><span :class="['metric-icon',card.tone]"><UiIcon :name="card.icon" :size="19" /></span></div><strong class="metric-value">{{ card.value }}</strong><p><span :class="['mini-dot',card.tone]" />{{ card.note }}</p></div></div><div class="dashboard-middle"><section class="panel revenue-panel"><div class="panel-heading"><div><h2>Revenue overview</h2><p class="muted">Pendapatan diterima dalam 7 hari terakhir</p></div><span class="subtle-tag">7 hari terakhir</span></div><div class="revenue-headline"><strong>{{ money((data?.chart || []).reduce((n,d)=>n+d.revenue,0)) }}</strong><span><span class="mini-dot green" />Pembayaran sukses</span></div><div class="chart"><div class="chart-grid"><span v-for="fraction in [1,.75,.5,.25,0]" :key="fraction">{{ new Intl.NumberFormat('id-ID',{notation:'compact',maximumFractionDigits:1}).format(Math.max(...(data?.chart||[]).map(d=>d.revenue),0)*fraction) }}</span></div><div class="chart-bars"><div v-for="(day,i) in data?.chart" :key="day.day" class="chart-column"><div class="bar-track"><div :class="['chart-bar',{current:i===6}]" :style="{height:Math.max(day.revenue/maxRevenue*100,2)+'%'}" :title="money(day.revenue)"><span>{{ money(day.revenue) }}</span></div></div><small>{{ new Date(day.day).toLocaleDateString('id-ID',{weekday:'short'}) }}</small></div></div></div></section><section class="panel location-panel"><div class="panel-heading"><div><h2>Lokasi hari ini</h2><p class="muted">Aktivitas di setiap cabang</p></div><NuxtLink to="/locations" class="icon-button" aria-label="Lihat lokasi"><UiIcon name="up" :size="18" /></NuxtLink></div><div v-for="(location,i) in data?.locations" :key="location.id" class="location-row"><span :class="['location-icon','location-'+i]"><UiIcon name="locations" :size="20" /></span><div><strong>{{ location.name }}</strong><small>{{ location.orders }} order hari ini</small><div class="progress-track"><span :style="{width:Math.max(location.orders / Math.max(metrics.ordersToday,1)*100,5)+'%'}" /></div></div><strong class="location-count">{{ location.orders }}<small>orders</small></strong></div><div class="location-footer"><UiIcon name="success" :size="16" /><span>{{ data?.locations?.filter(l => l.isActive).length || 0 }} lokasi aktif</span><NuxtLink to="/locations" class="text-link">Kelola lokasi <UiIcon name="right" :size="14" /></NuxtLink></div></section></div><section class="panel"><div class="panel-heading"><div><h2>Orders hari ini <span class="count">{{ metrics.ordersToday || 0 }}</span></h2><p class="muted">Ikuti setiap perjalanan pelayanan customer Anda.</p></div><NuxtLink to="/orders" class="text-link">Lihat semua orders <UiIcon name="arrow" :size="16" /></NuxtLink></div><OrderTable :orders="data?.orders?.slice(0,5) || []" /><div class="panel-footer"><span><span class="live-dot" />Diperbarui otomatis setiap 25 detik</span><button class="text-link" :disabled="status === 'pending'" @click="refresh"><UiIcon name="refresh" :size="14" />Refresh</button></div></section><div class="dashboard-bottom"><section class="panel"><div class="panel-heading"><div><h2>Tim therapist</h2><p class="muted">Ketersediaan tim untuk hari ini</p></div><NuxtLink to="/therapists" class="text-link">Lihat tim <UiIcon name="arrow" :size="15" /></NuxtLink></div><div class="therapist-strip"><div v-for="t in data?.therapists" :key="t.id" class="therapist-mini"><span class="avatar pastel">{{ initials(t.name) }}</span><div><strong>{{ t.name.split(' ')[0] }}</strong><small>{{ t.locations[0]?.name }}</small></div><span :class="['availability-dot',{available:t.availability==='AVAILABLE'}]" /></div></div></section><section class="small-insight"><span class="metric-icon green"><UiIcon name="done" :size="22" /></span><div><h3>Pelayanan yang tuntas</h3><p><strong>{{ metrics.completed || 0 }}</strong> treatment selesai hari ini.<br />Setiap detail membuat perbedaan.</p></div><UiIcon name="leaf" :size="46" /></section></div></div></template>